ee:variables.ee:set-variable:
%dw 2.0
output application/xml
ns ns0 http://tempuri.org/
ns ns01 http://www.etb.com.co/orquestador
---
{
	ns0#ProcesarOrden: {
		ns0#solicitudOrden: {
			ns01#Encabezado: {
				ns01#Propiedades: {
					ns01#Propiedad: {
						ns01#Nombre: "",
						ns01#Valor: ""
					}
				},
				ns01#Sistema: {
					ns01#IdCorrelacion: vars.orderNumber,
					ns01#Nombre: "MULESOFT",
					ns01#Servidor: "MULESOFT"
				}
			},
			ns01#DatosSolicitud: {
				ns01#EstadoOrden: vars.orderStatus.status,
				ns01#NumeroOrden: vars.orderNumber,
				ns01#Tramite: vars.orderData[0].Tramite.'Tipo_Tramite',
				ns01#UsuarioEvento: ""
			}
		}
	}
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var status = payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.Estado
var detalle = payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.DetalleEstado
var manexepcion = payload.ProcesarOrdenResponse.Resultado.Encabezado.Servicio.Codigo default ""
---
if(status == "OK")
{
  "status": status,
  "orderNumber": vars.orderNumber,
  "idServiceAccount": vars.orderData[0]."Servicio_Tramite"."Id_Cuenta_Servicio"
}
else if(manexepcion == "10609")
{
  "status": "OK",
  "orderNumber": vars.orderNumber,
  "idServiceAccount": vars.orderData[0]."Servicio_Tramite"."Id_Cuenta_Servicio",
  "message": detalle
}
else
{
  "status": 500,
  "code": "INTERNAL_SERVER_ERROR",
  "message": {
    "message": detalle
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}
